import {z} from 'zod';
import {ids,opaqueKey,sha256,revision,timestamp,gitCommit,artifactRef} from './primitives.js';

const text=z.string().trim().min(1).max(4096);
const status=z.enum(['PASS','FAIL','MISSING','STALE']);
export const candidateReviewItem=z.strictObject({itemId:opaqueKey,itemHash:sha256,kind:z.enum(['requirement','work-human','quality-human']),requirementIds:z.array(ids.requirement),subjectId:opaqueKey,checkId:opaqueKey,expected:z.string().min(1).max(32768)});
export const candidateHumanResult=z.strictObject({resultId:opaqueKey,operationId:ids.operation,candidateId:ids.candidate,candidateRevision:revision,manifestHash:sha256,item:candidateReviewItem,previousResultId:opaqueKey.nullable(),principalId:opaqueKey,verdict:z.enum(['PASS','FAIL']),procedure:text,expected:z.string().min(1).max(32768),observed:text,evidence:z.array(artifactRef).max(16),createdAt:timestamp});
export const candidateRejectionResult=z.strictObject({resultId:opaqueKey,operationId:ids.operation,candidateId:ids.candidate,candidateRevision:revision,manifestHash:sha256,rejectionId:opaqueKey,previousResultId:opaqueKey.nullable(),classification:z.enum(['IN_SCOPE_DEFECT','SCOPE_CHANGE']),state:z.enum(['OPEN','WITHDRAWN']),item:candidateReviewItem.nullable(),description:text,reason:text,evidence:z.array(artifactRef).max(16),principalId:opaqueKey,createdAt:timestamp,nextAction:z.enum(['REPAIR_REVIEW_REQUIRED','CHANGE_REVIEW_REQUIRED','NONE']),applicationState:z.literal('NOT_APPLIED')});
export const candidateReviewView=z.strictObject({candidateId:ids.candidate,candidateRevision:revision,manifestHash:sha256,qualification:z.enum(['CURRENT','STALE']),resourceRevision:revision,automaticStatus:z.literal('PASS'),humanStatus:status,reviewHash:sha256,items:z.array(candidateReviewItem.extend({status,result:candidateHumanResult.nullable()})).min(1).max(2048),automaticChecks:z.array(z.strictObject({operationId:ids.operation,checkId:opaqueKey,status:z.string(),codes:z.array(z.string())})),rejections:z.array(candidateRejectionResult).max(100),rejectionStatus:z.enum(['OPEN','NONE']),canRecord:z.boolean(),canPrepareAcceptance:z.boolean(),canWithdrawRejections:z.boolean()});
export const candidateReviewEntry=z.strictObject({runId:ids.run,codeCommit:gitCommit,review:candidateReviewView});
export const recordCandidateReviewInput=candidateHumanResult.pick({manifestHash:true,previousResultId:true,verdict:true,procedure:true,expected:true,observed:true,evidence:true}).extend({itemId:opaqueKey,itemHash:sha256});
export const recordCandidateRejectionInput=candidateRejectionResult.pick({manifestHash:true,rejectionId:true,previousResultId:true,classification:true,state:true,description:true,reason:true,evidence:true}).extend({itemId:opaqueKey.nullable(),itemHash:sha256.nullable()});
export const candidateReviewHistory=z.strictObject({items:z.array(z.strictObject({sequence:revision,result:candidateHumanResult})).max(100),nextSequence:revision.nullable()});
export const candidateRejectionHistory=z.strictObject({items:z.array(z.strictObject({sequence:revision,result:candidateRejectionResult})).max(100),nextSequence:revision.nullable()});
